  for(let e=0;e<4;e++){const k=(e+1)%4;if((v[e]>0)===(v[k]>0))continue;const t=v[e]/(v[e]-v[k]),a=corners[e],b=corners[k];cross.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}
  if(cross.length===2)points.push({...cross[0],move:true},cross[1]);
  else if(cross.length===4){const center=field(x+cellW/2,y+cellH/2),pair=(center>0)===(v[0]>0)?[[0,1],[2,3]]:[[0,3],[1,2]];for(const [a,b]of pair)points.push({...cross[a],move:true},cross[b]);}
