  const twists=1+2*Math.round(Math.abs(a)),v=(i/Math.max(1,n-1)-.5)*(50+Math.abs(b)*55);
  for(let j=0;j<=s;j++){const u=j/s*TAU,rr=220+v*Math.cos(twists*u/2)+Math.sin(u*3+Math.sin(pp))*c*5;points.push(projectLab3D(rr*Math.cos(u),rr*Math.sin(u),v*Math.sin(twists*u/2),pp,d));}break;
