  const detail=Math.max(4,Math.floor(s/2));for(let arc=0;arc<2;arc++)for(let j=0;j<=detail;j++){const u=j/detail*Math.PI/2+arc*Math.PI,r=radius+Math.sin(j/detail*Math.PI*2+pp)*c*cell*.015,x=(arc===0?-cell/2:cell/2)+Math.cos(u)*r,y=(arc===0?-cell/2:cell/2)+Math.sin(u)*r;points.push({x:cx+x*Math.cos(turn)-y*Math.sin(turn),y:cy+x*Math.sin(turn)+y*Math.cos(turn),move:j===0});}break;
