  for(let level=0;level<=bits.length;level++){from={x,y};if(level>0){const side=bits[level-1]==='1'?1:-1;heading+=side*angle+(hash01(i*17+level)-.5)*vary*d*.12+Math.sin(pp+level*.7)*depth*c*.045;}const length=125*Math.pow(decay,level);x+=Math.cos(heading)*length;y+=Math.sin(heading)*length;to={x,y};}
  for(let j=0;j<=s;j++){const t=j/s,bend=Math.sin(t*Math.PI)*Math.sin(pp+i*.13)*depth*c*3;points.push({x:from.x+(to.x-from.x)*t+bend,y:from.y+(to.y-from.y)*t});}break;
