  const circles=3+Math.round(Math.abs(c)),spacing=75+Math.abs(a)*40,radius=spacing*Math.sin(Math.PI/circles)*clamp(.85+Math.abs(b)*.12,.8,1.15);let x=(hash01(i*47)-.5)*400,y=(hash01(i*53)-.5)*400,previous=-1;
  for(let j=0;j<s+15;j++){let k=Math.floor(hash01(i*409+j*31+Math.round(d*7))*circles);if(k===previous)k=(k+1)%circles;previous=k;const angle=k/circles*TAU+Math.sin(pp)*depth*.15,cx=Math.cos(angle)*spacing*(1+.2*Math.sin(k*2.1+c)),cy=Math.sin(angle)*spacing*(1+.2*Math.cos(k*1.7+d)),dx=x-cx,dy=y-cy,scale=(radius*(.8+hash01(k*33+3)*.4))**2/Math.max(12,dx*dx+dy*dy);x=cx+dx*scale;y=cy+dy*scale;if(Math.abs(x)+Math.abs(y)>1e6){x=spacing;y=0;}if(j>=15)points.push({x:410*Math.tanh(x/250),y:410*Math.tanh(y/250)});}break;
