function rawPointsFor(i,p,chaos,warp){
 const o=elementSettings(i),local=i===CONFIG.selected?handValue('selected',o.chaos??1,2):(o.chaos??1);
 const q=chaos*local,variation=CONFIG.randomSpread,key=i*.041,s=CONFIG.steps;
 const px=(hash01(i*11+1)-.5)*760,py=(hash01(i*13+2)-.5)*760;
 const jitter=CONFIG.jitter*(o.jitter??1)*q,noiseAmount=warp*(o.noise??1)*q;
 const pp=p*CONFIG.noiseCycles,depth=CONFIG.motion;
 const a=CONFIG.a+Math.sin(pp)*depth*.055,b=CONFIG.b+Math.cos(pp)*depth*.055,c=CONFIG.c+Math.sin(pp)*depth*.04,d=CONFIG.d+Math.cos(pp)*depth*.04;
 const pts=[];let x=px,y=py,xx=hash01(i*31)*.1,yy=hash01(i*37)*.1;
 if(CONFIG.method===1||CONFIG.method===2){
  const next=()=>{const nx=CONFIG.method===1?Math.sin(a*yy)+c*Math.cos(a*xx):Math.sin(a*yy)-Math.cos(b*xx),ny=CONFIG.method===1?Math.sin(b*xx)+d*Math.cos(b*yy):Math.sin(c*xx)-Math.cos(d*yy);xx=nx;yy=ny;};
  for(let k=0;k<24+Math.floor(hash01(i*41)*120);k++)next();
  for(let j=0;j<s;j++){next();pts.push({x:xx*150,y:yy*150});}
 }else if(CONFIG.method===0){
  const k=CONFIG.noiseScale*.003,eps=.055;
  for(let j=0;j<s;j++){
   pts.push({x,y});const nx=x*k,ny=y*k,off=pp+key*.1;
   const dx=(nloop(nx,ny+eps,off,key*.01)-nloop(nx,ny-eps,off,key*.01))/(2*eps),dy=-(nloop(nx+eps,ny,off,key*.01)-nloop(nx-eps,ny,off,key*.01))/(2*eps);
   const angle=Math.atan2(dy,dx)*(0.5+Math.abs(CONFIG.c)) +CONFIG.twist*Math.hypot(x,y)*.004+CONFIG.a*.18+Math.sin(pp)*depth*.7+Math.sin((x+y)*.006*CONFIG.d)*CONFIG.d*.2;
   const step=3.5+Math.abs(CONFIG.b)*2.2+variation*hash01(i*19)*3;
   x+=Math.cos(angle)*step+Math.sin(pp+key)*depth*noiseAmount*.25;
   y+=Math.sin(angle)*step+Math.cos(pp+key)*depth*noiseAmount*.25;
  }
 }else if(CONFIG.method===3){
  const r=130+hash01(i*11)*160,phase=key*variation;
  for(let j=0;j<=s;j++){const u=j/s*TAU*2;
   pts.push({x:r*(Math.sin(u*(1+Math.abs(a))+phase+Math.sin(pp)*depth*.7)+.35*Math.sin(u*(1+Math.abs(c))+pp)),y:r*(Math.sin(u*(1+Math.abs(b))+phase+Math.cos(pp)*depth*.7)+.35*Math.cos(u*(1+Math.abs(d))-pp))});
  }
 }else if(CONFIG.method===4){
  const radius=35+i/Math.max(1,CONFIG.count-1)*370;
  for(let j=0;j<=s;j++){const u=j/s*TAU,rx=Math.cos(u)*radius,ry=Math.sin(u)*radius;
   const k=CONFIG.noiseScale*.004,w1=(nloop(rx*k,ry*k,pp+Math.sin(pp)*depth*.5)-.5)*120*noiseAmount;
   const w2=(nloop(rx*k+w1*.01+5,ry*k+w1*.01+3,pp,3)-.5)*70*noiseAmount*CONFIG.c;
   const radial=radius+w1+w2*.5+Math.sin(u*(2+Math.round(Math.abs(a)*2))+pp)*Math.abs(b)*9*q+Math.sin(u*(3+Math.round(Math.abs(d)*3))-pp)*d*4*q;
   pts.push({x:Math.cos(u+CONFIG.twist*w2*.002)*radial,y:Math.sin(u+CONFIG.twist*w2*.002)*radial});
  }
 }
 if(CONFIG.method>=5)pts.push(...advancedPoints(i,p,q,noiseAmount));
 // Seeded, loop-periodic per-element displacement; no screen-space glitch or image data.
 const dx=Math.sin(pp+key*3)*depth*12*q,dy=Math.cos(pp+key*5)*depth*12*q;
 for(let j=0;j<pts.length;j++){
  const v=pts[j],n=nloop(v.x*.005*CONFIG.noiseScale,v.y*.005*CONFIG.noiseScale,pp,key*.02)-.5;
  const jx=Math.sin(pp*3+j*.7+key*9)*hash01(i*89+j)*jitter*22,jy=Math.cos(pp*2+j*.9+key*7)*hash01(i*97+j)*jitter*22;
  v.x+=dx+n*noiseAmount*30+jx;v.y+=dy+n*noiseAmount*30+jy;
 }
 return pts;
}
function renderMethodInk(seconds){
 if(!ink)return;methodFrameCache={};if(lastNoiseSeed!==CONFIG.seed){noiseSeed(CONFIG.seed);randomSeed(CONFIG.seed);lastNoiseSeed=CONFIG.seed;}
 const p=TAU*((seconds%CONFIG.loopSeconds)/CONFIG.loopSeconds),ctx=ink.drawingContext;
 ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.clearRect(0,0,ART_W,ART_H);
 const chaos=handValue('chaos',CONFIG.chaos),warp=handValue('warp',CONFIG.warp,2);
 ctx.translate(CONFIG.centerX*10,CONFIG.centerY*10);ctx.rotate(CONFIG.rotation/180*Math.PI);ctx.scale(CONFIG.scale,CONFIG.scale);ctx.lineCap='round';ctx.lineJoin='round';
 for(let i=0;i<CONFIG.count;i++){
  const pts=pointsFor(i,p,chaos,warp),o=elementSettings(i),strength=o.glow??1;if(strength===0)continue;
  ctx.strokeStyle=ctx.fillStyle=colorFor(i,p,CONFIG.opacity*strength*((CONFIG.method===1||CONFIG.method===2)?.44:1));ctx.lineWidth=CONFIG.strokeWidth*(.7+hash01(i*5)*.6);
  for(let copy=0;copy<CONFIG.symmetry;copy++){
   ctx.save();ctx.rotate(copy/CONFIG.symmetry*TAU);
   if(CONFIG.style===0){ctx.beginPath();for(let j=0;j<pts.length;j++){const v=pts[j];if(j===0||v.move)ctx.moveTo(v.x,v.y);else ctx.lineTo(v.x,v.y);}ctx.stroke();}
   else for(let j=0;j<pts.length;j+=(CONFIG.style===2?3:1)){const v=pts[j],size=CONFIG.strokeWidth*(CONFIG.style===2?3.5:1.25);if(CONFIG.style===2){ctx.strokeRect(v.x-size/2,v.y-size/2,size,size);}else ctx.fillRect(v.x,v.y,size,size);}
   ctx.restore();
  }
 }
 ctx.setTransform(1,0,0,1,0,0);
}

function renderAt(seconds){const result=withMappedConfig(()=>drawProceduralAt((audioMappingValues.phase!==undefined||activeMappingValues.phase!==undefined)?CONFIG.phase/100*CONFIG.loopSeconds:seconds));mappingNeedsRender=false;audioNeedsRender=false;return result;}
function refreshArtwork(){syncControls();updateMappings(performance.now(),true);updateAudio(performance.now(),true);renderAt(clockSeconds);}
function setStatus(text){const el=document.getElementById('signal-status');el.textContent=text;localizeUI(el);}
function setSeed(){CONFIG.seed=Math.floor(Math.random()*1000000);clockSeconds=0;refreshArtwork();}
function syncSelected(){CONFIG.selected=Math.min(CONFIG.selected,CONFIG.count-1);const o=elementSettings(CONFIG.selected);for(const k of ['Chaos','Noise','Jitter','Glow'])CONFIG['item'+k]=o[k.toLowerCase()]??1;}
function setMethod(){const m=METHODS[CONFIG.method];[CONFIG.a,CONFIG.b,CONFIG.c,CONFIG.d]=m.p;CONFIG.count=m.count;CONFIG.steps=m.steps;CONFIG.style=m.style;elementOverrides={};CONFIG.selected=0;syncSelected();clockSeconds=0;}


function syncMethodButtons(){
 const menu=document.getElementById('method-menu');if(!menu)return;
 const index=Math.round(clamp(effectiveValue('method'),0,METHODS.length-1)),method=METHODS[index];
 for(const button of menu.querySelectorAll('.method-button'))button.setAttribute('aria-pressed',String(Number(button.dataset.method)===index));
 document.getElementById('method-number').textContent=String(index+1).padStart(2,'0');document.getElementById('method-total').textContent=METHODS.length;
 for(const [id,text]of [['method-name',method.name],['method-description',method.explain],['method-use',method.use],['method-parameters',PARAMETER_GUIDES[index]]]){const el=document.getElementById(id);el.textContent=text;localizeUI(el);}
 document.getElementById('method-hand-note').hidden=!('method' in activeMappingValues)&&!('method' in audioMappingValues);
}

function syncControls(){
 syncSelected();for(const spec of SLIDERS){const [key,,, ,step]=spec;const input=document.getElementById('setting-'+key);if(!input)continue;input.value=CONFIG[key];if(key==='selected')input.max=CONFIG.count-1;document.getElementById('value-'+key).textContent=key==='method'?METHODS[CONFIG.method].name:key==='style'?['Lines','Dots','Squares'][CONFIG.style]:step===1?String(CONFIG[key]):Number(CONFIG[key]).toFixed(2);}
 syncMethodButtons();
 for(const key of ['handApply','mirrorCamera','showLandmarks','showPointIds','previewAxes','swapHandLabels'])document.getElementById('hand-'+key).checked=CONFIG[key];
 document.getElementById('hand-min-confidence').value=CONFIG.handMinConfidence;document.getElementById('hand-min-confidence-value').textContent=Math.round(CONFIG.handMinConfidence*100)+'%';document.getElementById('hand-data-space').value=CONFIG.handDataSpace;updateHandUI();setLanguage(CONFIG.language);
}
function exportSettings(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({format:'p5-sketch-lab-v3',settings:CONFIG,elements:elementOverrides,handMappings:serializeMappings(),remix:serializeRemix(),audio:serializeAudio()},null,2)],{type:'application/json'}));a.href=url;a.download='sketch-lab-'+CONFIG.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function applySettings(data){
 if(!['p5-sketch-lab-v1','p5-sketch-lab-v2','p5-sketch-lab-v3'].includes(data?.format)||!data.settings)throw new Error('Choose a Sketch Lab settings file.');
 const next={...DEFAULT_CONFIG,language:CONFIG.language},s=data.settings;
 for(const [k,,min,max,step] of SLIDERS)if(Number.isFinite(s[k]))next[k]=Math.max(min,Math.min(max,step===1?Math.round(s[k]):s[k]));
 if(['en','my'].includes(s.language))next.language=s.language;
 if(['chaos','warp','glow','selected'].includes(s.handTarget))next.handTarget=s.handTarget;
 for(const [k,min,max] of [['handStrength',0,1],['handSmoothing',.03,.8]])if(Number.isFinite(s[k]))next[k]=Math.max(min,Math.min(max,s[k]));
 for(const k of ['handApply','mirrorCamera','showLandmarks','showPointIds','previewAxes','swapHandLabels'])if(typeof s[k]==='boolean')next[k]=s[k];if(Number.isFinite(s.handMinConfidence))next.handMinConfidence=clamp(s.handMinConfidence,0,1);if(['image','world'].includes(s.handDataSpace))next.handDataSpace=s.handDataSpace;
 elementOverrides={};for(const [id,v] of Object.entries(data.elements||{})){if(!/^\d+$/.test(id)||+id>=600||!v||typeof v!=='object')continue;const o={};for(const k of ['chaos','noise','jitter','glow'])if(Number.isFinite(v[k]))o[k]=Math.max(0,Math.min(2,v[k]));elementOverrides[id]=o;}
 Object.assign(CONFIG,next);loadRemix(data.remix);loadAudioSettings(data.audio);loadMappings(data.format!=='p5-sketch-lab-v1'?(data.handMappings||[]):undefined,next.handTarget,next.handStrength);clockSeconds=CONFIG.phase/100*CONFIG.loopSeconds;refreshArtwork();setStatus('SETTINGS LOADED');
}

