function recordingMimes(format,withAudio=false){const mp4=['video/mp4;codecs=avc1.640028','video/mp4;codecs=avc1.42E028','video/mp4'],webm=['video/webm;codecs=vp8','video/webm;codecs=vp9','video/webm'];const choices=withAudio?(format==='mp4'?['video/mp4;codecs=avc1.640028,mp4a.40.2','video/mp4']:format==='webm'?['video/webm;codecs=vp8,opus','video/webm']:['video/mp4;codecs=avc1.640028,mp4a.40.2','video/mp4;codecs=avc1.42E028,mp4a.40.2','video/webm;codecs=vp8,opus','video/webm','video/mp4']):(format==='mp4'?mp4:format==='webm'?webm:[...mp4,...webm]);return choices.filter(m=>{try{return MediaRecorder.isTypeSupported(m);}catch(e){return false;}});}
