  stream=art.elt.captureStream(fps);if(withAudio){const track=audioState.destination?.stream.getAudioTracks()[0];if(!track)throw new Error('audio');stream.addTrack(track.clone());}const options={videoBitsPerSecond:12000000,audioBitsPerSecond:192000};if(mime)options.mimeType=mime;
