  h.inferenceFPS=0;h.inferenceMs=0;h.lastResultTime=0;h.hands={Left:null,Right:null};h.lastResult=null;resetMappingRuntime();updateMappings(performance.now(),true);updateHandUI();drawHandOverlay();handStatus('CAMERA OFF · MANUAL CONTROLS');
