async function toggleHands(){
  const h=handControl;if(h.enabled||h.pending){stopHands();return;}
  if(!navigator.mediaDevices?.getUserMedia){handStatus('Camera access requires HTTPS or localhost. Manual controls still work.');return;}
  const request=++h.request;h.pending=true;updateHandUI();handStatus('LOADING HAND MODEL…');
  try{
    await loadHandModel();if(request!==h.request)return;
    handStatus('ALLOW CAMERA ACCESS TO START TRACKING');
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});
    if(request!==h.request){stream.getTracks().forEach(t=>t.stop());return;}
    h.stream=stream;h.video=document.getElementById('hand-video');h.video.srcObject=stream;await h.video.play();
    if(request!==h.request)return;
    h.enabled=true;h.pending=false;h.lastInference=0;h.lastVideoTime=-1;
    document.getElementById('hand-feed').style.aspectRatio=h.video.videoWidth+'/'+Math.max(1,h.video.videoHeight);
    stream.getVideoTracks().forEach(t=>t.addEventListener('ended',()=>{if(h.enabled)stopHands();}));
    updateHandUI();handStatus('CAMERA LIVE · SHOW ONE OR BOTH HANDS');
  }catch(error){
    if(request!==h.request)return;stopHands();
    handStatus(error.name==='NotAllowedError'?'Camera permission was denied. Allow the camera to see tracking data.':'Could not load the camera or hand model. Check internet and camera access.');
    console.warn('Hand tracking:',error);
  }
}


function updateHands(now){
  const h=handControl,v=h.video;if(!h.enabled||!h.model||!v||v.readyState<2||now-h.lastInference<100||v.currentTime===h.lastVideoTime)return;
  h.lastInference=now;h.lastVideoTime=v.currentTime;
  try{const start=performance.now(),result=h.model.detectForVideo(v,now);consumeHandResult(result,now,performance.now()-start);}
  catch(error){stopHands();handStatus('Tracking stopped. Restart the camera, or use manual controls.');console.warn('Hand inference:',error);}
}


async function loadHandModel() {
  if(handControl.model) return handControl.model;
  if(!handControl.modelPromise) {
    handControl.modelPromise=(async()=>{
      const base='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@'+MEDIAPIPE_VERSION;
      const {FilesetResolver,HandLandmarker}=await import(base+'/vision_bundle.mjs');
      const files=await FilesetResolver.forVisionTasks(base+'/wasm');
      return HandLandmarker.createFromOptions(files,{
        baseOptions:{modelAssetPath:HAND_MODEL,delegate:'CPU'},
        runningMode:'VIDEO',numHands:2,
        minHandDetectionConfidence:.5,minHandPresenceConfidence:.5,
        minTrackingConfidence:.5
      });
    })();
  }
  try {handControl.model=await handControl.modelPromise;return handControl.model;}
  catch(error) {handControl.modelPromise=null;throw error;}
}
// Independent routes from two-hand telemetry to any artwork variable.
