const REMIX_AUDIO_CSS=`
 #remix-panel,#audio-panel{border:1px solid #555;padding:12px;margin:16px 0}#remix-panel h2,#audio-panel h2{letter-spacing:1px}.remix-card,.audio-route{border:1px solid #444;padding:10px;margin:12px 0;background:#101010}.remix-card summary,.audio-route summary{display:flex;justify-content:space-between;gap:8px}.mix-checks{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0}.mix-checks label{display:flex;gap:5px;align-items:center}.remix-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:9px}.remix-controls{display:grid;grid-template-columns:1fr;gap:0}.remix-select{margin-bottom:9px}.remix-card .setting,.audio-route .setting{margin:10px 0}#audio-player{width:100%;height:36px;margin-top:10px}#audio-spectrum{width:100%;height:80px;display:block;border:1px solid #333;background:#080808;margin-top:10px}.audio-meters{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:10px 0}.audio-meter{font-size:9px;min-width:0}.audio-meter div{display:flex;justify-content:space-between;gap:4px}.audio-meter progress,.audio-route progress{width:100%;height:5px;accent-color:#ddd}.audio-route-readout{font-size:10px;margin:10px 0;overflow-wrap:anywhere}#audio-status,#audio-file-name{font-size:10px;overflow-wrap:anywhere;margin:8px 0}.compact-selects{display:grid;grid-template-columns:1fr 1fr;gap:8px}.remix-card button,.audio-route button{min-height:44px;font-size:9px;overflow-wrap:anywhere;white-space:normal}.custom-hint{font-size:9px;color:#999;line-height:1.8}html[lang=my] .custom-hint{font-size:10px}#audio-panel fieldset{border:0;padding:0;margin:0;min-width:0}
`;
function methodOptions(selected){return METHODS.map((m,i)=>`<option value="${i}" ${i===selected?'selected':''}>${m.name}</option>`).join('');}
function customSlider(prefix,key,label,value,min,max,step){return `<div class="setting"><div class="setting-heading"><label for="${prefix}-${key}">${label}</label><output data-custom-value="${key}">${Number(value).toFixed(step===1?0:2)}</output></div><input type="range" id="${prefix}-${key}" data-custom-key="${key}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function remixPanelHTML(){return `<section id="remix-panel"><h2>METHOD REMIXER</h2><div class="mix-checks"><label><input id="remix-enabled" type="checkbox">Enable remix</label><label><input id="remix-main" type="checkbox" checked>Include main method</label></div><div class="setting"><label for="remix-main-opacity">Main opacity</label><input id="remix-main-opacity" type="range" min="0" max="1" step=".01" value="1"></div><label for="remix-add-method">Choose a method to layer</label><select id="remix-add-method">${methodOptions(0)}</select><button id="remix-add" class="accent" style="margin-top:8px">ADD LAYER</button><div class="hint">Stack methods, reorder layers and blend their light. Each layer can also morph into a second method. More layers increase rendering work.</div><div id="remix-cards"></div></section>`;}
function audioPanelHTML(){return `<section id="audio-panel"><h2>AUDIO REACTIVE</h2><div class="compact-selects"><div><label for="audio-source">Audio source</label><select id="audio-source"><option value="mic">Microphone</option><option value="file">Audio file</option></select></div><button id="audio-start" class="accent">START AUDIO</button></div><div class="mix-checks"><label><input id="audio-reactive" type="checkbox" checked>Apply audio to art</label><label><input id="audio-file-loop" type="checkbox" checked>Loop audio file</label></div><button id="audio-load">LOAD AUDIO FILE</button><div id="audio-file-name">No audio file loaded</div><audio id="audio-player" controls preload="metadata" loop></audio><div id="audio-status" role="status">AUDIO OFF</div><canvas id="audio-spectrum" width="640" height="120" aria-label="Live frequency spectrum"></canvas><div class="hint">20 Hz → 20 kHz · logarithmic</div><div class="audio-meters">${[['rms','Loudness'],['bass','Bass'],['mid','Mids'],['treble','Treble'],['transient','Transient']].map(([key,label])=>`<div class="audio-meter"><div><span>${label}</span><span id="audio-level-${key}">0%</span></div><progress id="audio-meter-${key}" max="1" value="0" aria-label="${label}"></progress></div>`).join('')}</div><details><summary>Frequency & smooth response</summary>${AUDIO_SPECS.map(([key,label,min,max,step])=>`<div class="setting"><div class="setting-heading"><label for="audio-setting-${key}">${label}</label><output id="audio-value-${key}"></output></div><input id="audio-setting-${key}" type="range" min="${min}" max="${max}" step="${step}"></div>`).join('')}<label for="audio-fft">FFT size</label><select id="audio-fft">${[256,512,1024,2048,4096,8192,16384].map(v=>`<option value="${v}" ${v===2048?'selected':''}>${v}</option>`).join('')}</select><div class="hint"><span>Frequency resolution</span>: <span id="audio-resolution">—</span></div></details><div class="hint">Gain and filters affect analysis. File volume changes listening only. The microphone is never sent to your speakers. Audio starts only when you enable it.</div><button id="audio-add-route" style="margin-top:10px">ADD AUDIO MAPPING</button><div id="audio-routes"></div><div class="hint">For independent remix layers, choose that layer in Control scope.</div><div class="hint">Audio blends after hand control. Reduce Influence to share a variable. A one-loop recording holds live hand and audio modulation; a normal recording captures live changes.</div></section>`;}
function syncRemixUI(){const el=document.getElementById('remix-enabled');if(!el)return;el.checked=remixState.enabled;document.getElementById('remix-main').checked=remixState.includeMain;document.getElementById('remix-main-opacity').value=remixState.mainOpacity;}
function renderRemixCards(){
 const root=document.getElementById('remix-cards');if(!root)return;
 root.innerHTML=remixState.layers.map((l,index)=>`<details class="remix-card" id="remix-layer-${l.id}" open><summary><span>Layer</span><span>${index+1}</span></summary><div class="mix-checks">${[['enabled','Enabled'],['solo','Solo'],['followMain','Follow main sliders']].map(([key,label])=>`<label><input data-layer-key="${key}" type="checkbox" ${l[key]?'checked':''}>${label}</label>`).join('')}</div><label for="layer-${l.id}-method">Drawing method</label><select id="layer-${l.id}-method" data-layer-key="method">${methodOptions(l.method)}</select><div class="hint">${METHODS[l.method].use}</div><label for="layer-${l.id}-blend">Blend mode</label><select id="layer-${l.id}-blend" data-layer-key="blend">${BLEND_MODES.map(([value,label])=>`<option value="${value}" ${l.blend===value?'selected':''}>${label}</option>`).join('')}</select>${LAYER_EXTRA.map(([key,label,min,max,step])=>customSlider('layer-'+l.id,key,label,l[key],min,max,step)).join('')}<details><summary>Morph partner</summary><select data-layer-key="methodB" aria-label="Morph partner">${methodOptions(l.methodB)}</select>${['a','b','c','d'].map((key,j)=>customSlider('secondary-'+l.id,'secondary'+j,'Parameter '+key.toUpperCase(),l.secondary[j],-3,3,.01)).join('')}<div class="hint">Morph resamples paths by distance. Dots and disconnected paths can change structure during a blend.</div></details><details><summary>Layer variables</summary><div class="hint">These values are independent unless Follow main sliders is enabled.</div><fieldset style="border:0;padding:0;margin:0;min-width:0" ${l.followMain?'disabled':''}>${GROUPS.filter(g=>!['Loop & transport','One individual element'].includes(g[0])).map(([name,,specs])=>`<details><summary>${name}</summary>${specs.filter(s=>s[0]!=='method').map(([key,label,min,max,step])=>customSlider('param-'+l.id,key,label,l.parameters[key],min,max,step)).join('')}</details>`).join('')}</fieldset><button data-layer-action="capture">CAPTURE MAIN SETTINGS</button></details><div class="remix-actions"><button data-layer-action="up">MOVE UP</button><button data-layer-action="down">MOVE DOWN</button><button data-layer-action="duplicate">DUPLICATE LAYER</button><button data-layer-action="remove">REMOVE LAYER</button></div></details>`).join('');
 for(const l of remixState.layers){const card=document.getElementById('remix-layer-'+l.id);for(const input of card.querySelectorAll('[data-layer-key]'))input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{const key=input.dataset.layerKey;l[key]=input.type==='checkbox'?input.checked:['method','methodB'].includes(key)?Number(input.value):input.value;if(key==='method'){const m=METHODS[l.method];Object.assign(l.parameters,{method:l.method,a:m.p[0],b:m.p[1],c:m.p[2],d:m.p[3],count:m.count,steps:m.steps,style:m.style});renderRemixCards();}if(key==='followMain')renderRemixCards();if(key==='methodB'){l.secondary=[...METHODS[l.methodB].p];renderRemixCards();}renderAt(clockSeconds);});
  for(const input of card.querySelectorAll('[data-custom-key]'))input.addEventListener('input',()=>{const key=input.dataset.customKey,value=Number(input.value);if(key.startsWith('secondary'))l.secondary[+key.slice(9)]=value;else if(LAYER_EXTRA.some(s=>s[0]===key))l[key]=value;else l.parameters[key]=value;input.parentElement.querySelector('[data-custom-value]').textContent=value.toFixed(2);renderAt(clockSeconds);});
  for(const button of card.querySelectorAll('[data-layer-action]'))button.addEventListener('click',()=>{const action=button.dataset.layerAction,index=remixState.layers.indexOf(l);if(action==='remove'){remixState.layers.splice(index,1);audioRoutes=audioRoutes.filter(r=>r.scope!==String(l.id));}else if(action==='duplicate'){const copy=cloneData(l);copy.id=remixState.nextId++;remixState.layers.splice(index+1,0,copy);audioRoutes.push(...audioRoutes.filter(r=>r.scope===String(l.id)).map(r=>({...r,id:nextAudioRouteId++,scope:String(copy.id)})));}else if(action==='capture'){l.parameters={...CONFIG,method:l.method};l.elements=cloneData(elementOverrides);}else{const next=index+(action==='up'?-1:1);if(next>=0&&next<remixState.layers.length)[remixState.layers[index],remixState.layers[next]]=[remixState.layers[next],remixState.layers[index]];}renderRemixCards();renderAudioRoutes();updateAudio(performance.now(),true);renderAt(clockSeconds);});
 }localizeUI(root);
}
function audioScopeOptions(selected){return [['main','Main artwork'],...remixState.layers.map((l,i)=>[String(l.id),'Layer '+(i+1)])].map(([key,label])=>`<option value="${key}" ${key===selected?'selected':''}>${label}</option>`).join('');}
function renderAudioRoutes(){
 const root=document.getElementById('audio-routes');if(!root)return;root.innerHTML=audioRoutes.map((r,index)=>{const specs=r.scope==='main'?SLIDERS:layerSpecs(),spec=audioTargetSpec(r);return `<details class="audio-route" id="audio-route-${r.id}" open><summary><span>Audio mapping</span><span>${index+1}</span></summary><div class="mix-checks">${[['enabled','Enabled'],['invert','Invert'],['followResponse','Use global attack/release']].map(([key,label])=>`<label><input data-audio-key="${key}" type="checkbox" ${r[key]!==false?'checked':''}>${label}</label>`).join('')}</div><div class="compact-selects"><div><label>Audio signal</label><select data-audio-key="signal" aria-label="Audio signal">${AUDIO_SIGNALS.map(([key,label])=>`<option value="${key}" ${r.signal===key?'selected':''}>${label}</option>`).join('')}</select></div><div><label>Control scope</label><select data-audio-key="scope" aria-label="Control scope">${audioScopeOptions(r.scope)}</select></div></div><label>Artwork variable</label><select data-audio-key="target" aria-label="Artwork variable">${specs.map(([key,label])=>`<option value="${key}" ${r.target===key?'selected':''}>${label}</option>`).join('')}</select><div ${r.signal==='band'?'':'hidden'}>${customSlider('ar-'+r.id,'low','Low frequency · Hz',r.low,20,20000,1)}${customSlider('ar-'+r.id,'high','High frequency · Hz',r.high,20,20000,1)}</div>${customSlider('ar-'+r.id,'outMin','Output minimum',r.outMin,spec[2],spec[3],spec[4])}${customSlider('ar-'+r.id,'outMax','Output maximum',r.outMax,spec[2],spec[3],spec[4])}${customSlider('ar-'+r.id,'influence','Influence',r.influence,0,1,.01)}${customSlider('ar-'+r.id,'curve','Response curve',r.curve,.2,3,.05)}<div ${r.followResponse!==false?'hidden':''}>${customSlider('ar-'+r.id,'attack','Attack · seconds',r.attack,.005,1,.005)}${customSlider('ar-'+r.id,'release','Release · seconds',r.release,.03,3,.01)}</div><div class="audio-route-readout"><div data-audio-read="status">AUDIO OFF</div><progress max="1" value="0" aria-label="Audio response"></progress><div><span>Live target value</span>: <span data-audio-read="value">—</span></div></div><div class="grid2"><button data-audio-action="duplicate">DUPLICATE ROUTE</button><button data-audio-action="remove">REMOVE ROUTE</button></div></details>`;}).join('');
 for(const r of audioRoutes){const card=document.getElementById('audio-route-'+r.id);for(const input of card.querySelectorAll('[data-audio-key]'))input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{const key=input.dataset.audioKey;r[key]=input.type==='checkbox'?input.checked:input.value;if(key==='scope'||key==='target'){if(!audioTargetSpec(r))r.target='opacity';const spec=audioTargetSpec(r);r.outMin=spec[2];r.outMax=spec[3];}audioRuntime.delete(r.id);renderAudioRoutes();updateAudio(performance.now(),true);renderAt(clockSeconds);});
  for(const input of card.querySelectorAll('[data-custom-key]'))input.addEventListener('input',()=>{r[input.dataset.customKey]=Number(input.value);input.parentElement.querySelector('[data-custom-value]').textContent=Number(input.value).toFixed(2);updateAudio(performance.now(),true);renderAt(clockSeconds);});
  for(const button of card.querySelectorAll('[data-audio-action]'))button.addEventListener('click',()=>{if(button.dataset.audioAction==='remove'){audioRoutes=audioRoutes.filter(x=>x!==r);audioRuntime.delete(r.id);}else audioRoutes.push({...r,id:nextAudioRouteId++});renderAudioRoutes();updateAudio(performance.now(),true);renderAt(clockSeconds);});
 }localizeUI(root);updateAudioReadouts();
}
function wireRemixAudio(on){
 on('remix-enabled','change',e=>{remixState.enabled=e.target.checked;renderAt(clockSeconds);});on('remix-main','change',e=>{remixState.includeMain=e.target.checked;renderAt(clockSeconds);});on('remix-main-opacity','input',e=>{remixState.mainOpacity=Number(e.target.value);renderAt(clockSeconds);});on('remix-add','click',()=>createRemixLayer(Number(document.getElementById('remix-add-method').value)));
 on('audio-start','click',startAudio);on('audio-source','change',e=>{audioState.settings.source=e.target.value;});on('audio-reactive','change',e=>{audioState.settings.reactive=e.target.checked;updateAudio(performance.now(),true);renderAt(clockSeconds);});on('audio-file-loop','change',e=>{audioState.settings.fileLoop=e.target.checked;document.getElementById('audio-player').loop=e.target.checked;});
 const file=document.createElement('input');file.type='file';file.accept='audio/*';file.hidden=true;document.body.appendChild(file);on('audio-load','click',()=>file.click());file.onchange=()=>{if(!file.files[0])return;stopAudio();const a=audioState,player=document.getElementById('audio-player'),old=a.fileURL;a.fileURL=URL.createObjectURL(file.files[0]);a.fileName=file.files[0].name;player.src=a.fileURL;player.load();if(old)URL.revokeObjectURL(old);a.settings.source='file';syncAudioUI();file.value='';};
 const player=document.getElementById('audio-player');player.addEventListener('play',()=>{if(audioState.active)audioState.context?.resume();else if(!audioState.pending&&audioState.fileURL&&audioState.settings.source==='file')startAudio();});player.addEventListener('error',()=>{if(audioState.fileURL){stopAudio();audioStatus('Could not play this audio file. Choose another format.');}});
 for(const [key]of AUDIO_SPECS)on('audio-setting-'+key,'input',e=>{const s=audioState.settings;s[key]=Number(e.target.value);if(s.floor>=s.ceiling){if(key==='floor')s.ceiling=s.floor+1;else s.floor=s.ceiling-1;}if(s.highpass>=s.lowpass){if(key==='highpass')s.lowpass=s.highpass+1;else s.highpass=s.lowpass-1;}applyAudioSettings();syncAudioUI();});on('audio-fft','change',e=>{audioState.settings.fft=Number(e.target.value);applyAudioSettings();});
 on('audio-add-route','click',()=>{audioRoutes.push({...AUDIO_ROUTE_DEFAULT,id:nextAudioRouteId++,followResponse:true});renderAudioRoutes();});syncRemixUI();renderRemixCards();syncAudioUI();renderAudioRoutes();
}

