Object.assign(MY_MESSAGES,{"Cycles per loop": "ပတ်လမ်းတစ်ပတ်အတွင်း အကြိမ်ရေ", "Filter resonance · Q": "ဖြတ်စစ်တုန်ခါတင်မှု · Q", "Transient sensitivity": "ခဏတာခုန်ချက် အာရုံခံနှုန်း", "Transient averaging · seconds": "ခုန်ချက် ပျမ်းမျှညှိချိန် · စက္ကန့်", "Camera tracking uses video only. Audio is enabled separately. Internet is needed to load MediaPipe.": "ကင်မရာခြေရာခံမှုသည် ဗီဒီယိုကိုသာ သုံးသည်။ အသံစနစ်ကို သီးခြားဖွင့်နိုင်သည်။ MediaPipe ရယူရန် အင်တာနက် လိုအပ်သည်။", "20 Hz → 20 kHz · logarithmic": "20 Hz → 20 kHz · လော်ဂရစ်သမ်စကေး", "For independent remix layers, choose that layer in Control scope.": "သီးခြားရောစပ်အလွှာအတွက် ထိန်းချုပ်မည့်အပိုင်းတွင် သက်ဆိုင်ရာအလွှာကို ရွေးပါ။"});
const TEXT_SOURCES=new WeakMap(),ATTRIBUTE_SOURCES=new WeakMap();
function localizedText(text){
  const raw=text.trim(),my=CONFIG.language==='my';
  let m;
  m=raw.match(/^Layer (\d+)$/);if(m)return my?'အလွှာ '+m[1]:raw;
  m=raw.match(/^RECORDING · ([\d.]+) s$/);if(m)return my?'မှတ်တမ်းတင်နေသည် · '+m[1]+' စက္ကန့်':raw;
  m=raw.match(/^VIDEO READY · ([\d.]+) MB$/);if(m)return my?'ဗီဒီယို အဆင်သင့် · '+m[1]+' MB':raw;
  if(my){
    m=raw.match(/^([\d.]+) palms$/);if(m)return m[1]+' လက်ဖဝါးအလျား';
    m=raw.match(/^([\d.]+) \/s$/);if(m)return m[1]+' / စက္ကန့်';
  }
  if(!my||!MY_MESSAGES[raw])return text;
  return text.replace(raw,MY_MESSAGES[raw]);
}
function localizeUI(root=document.getElementById('signal-workspace')){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  for(let n=walker.nextNode();n;n=walker.nextNode()){
    if(!n.textContent.trim()||['SCRIPT','STYLE'].includes(n.parentElement?.tagName))continue;
    if(!TEXT_SOURCES.has(n))TEXT_SOURCES.set(n,n.textContent);
    const next=localizedText(TEXT_SOURCES.get(n));if(n.textContent!==next)n.textContent=next;
  }
  const elements=[root,...root.querySelectorAll('[aria-label],[title],[placeholder],optgroup[label]')];
  for(const el of elements){
    if(!ATTRIBUTE_SOURCES.has(el))ATTRIBUTE_SOURCES.set(el,{});const originals=ATTRIBUTE_SOURCES.get(el);
    for(const key of ['aria-label','title','placeholder','label'])if(el.hasAttribute(key)){
      if(!(key in originals))originals[key]=el.getAttribute(key);el.setAttribute(key,localizedText(originals[key]));
    }
  }
}
function setLanguage(language){
  CONFIG.language=language==='my'?'my':'en';document.documentElement.lang=CONFIG.language;
  try{localStorage.setItem('redSignalLanguage',CONFIG.language);}catch(error){}
  const select=document.getElementById('signal-language');if(select)select.value=CONFIG.language;
  localizeUI();
}


